local timesprinted = 0
hook.Add("StartCommand", "PrintRavenLogo", function()
	if timesprinted >= 1 then -- just in case the hook.remove doesn't work (which it should always)
		return
	end

	timesprinted = timesprinted + 1
	for i = 1, #blocks do
		MsgC(unpack(blocks[i]))
		MsgC("\n")
	end
	hook.Remove("StartCommand", "PrintRavenLogo")
end)
